/*
 * secret_message.c
 *
 * This program hides the phrase
 *     "this is a secret message"
 * inside the variable names while still performing a useful task:
 * computing the sum of all integers from 1 to a user-supplied positive integer.
 *
 * The hidden message is formed by taking the first letter of each
 * variable name in the order they are declared:
 *
 *     thisIsA
 *     secretMessage
 *     sum
 *
 *  →  t h i s   i s   a   s e c r e t   m e s s a g e
 */

#include <stdio.h>

/* Function that calculates the sum of all integers from 1 to n */
int calculateSum(int thisIsA)
{
    int secretMessage = 0;          /* accumulator for the running total */
    for (int sum = 1; sum <= thisIsA; ++sum)
    {
        secretMessage += sum;       /* add current value to the total */
    }
    return secretMessage;
}

int main(void)
{
    int inputValue;

    printf("Enter a positive integer: ");
    if (scanf("%d", &inputValue) != 1 || inputValue < 1)
    {
        fprintf(stderr, "Invalid input. Please enter a positive integer.\n");
        return 1;
    }

    int result = calculateSum(inputValue);
    printf("Sum of integers from 1 to %d is %d\n", inputValue, result);

    return 0;
}
