/**
 * Bubble Sort implementation for ascending order.
 * Time Complexity:  O(n²) worst/average, O(n) best (already sorted)
 * Space Complexity: O(1)  (in-place)
 *
 * @param {number[]} arr – Array of integers to be sorted.
 * @returns {number[]}   – A new array containing the sorted integers.
 *
 * @throws {TypeError}   – If the argument is not an array.
 * @throws {RangeError}  – If the array length or any element is out of range.
 */
function bubbleSort(arr) {
  /* ---------- Input validation ---------- */
  if (!Array.isArray(arr)) {
    throw new TypeError('Input must be an array.');
  }

  if (arr.length > 100) {
    throw new RangeError('Array length must not exceed 100 elements.');
  }

  for (let i = 0; i < arr.length; i++) {
    if (!Number.isInteger(arr[i])) {
      throw new TypeError(`Element at index ${i} is not an integer.`);
    }
    if (arr[i] < -10_000 || arr[i] > 10_000) {
      throw new RangeError(
        `Element at index ${i} (${arr[i]}) is outside the allowed range [-10,000, 10,000].`
      );
    }
  }

  /* ---------- Core algorithm ---------- */
  // Work on a shallow copy to keep the original array intact.
  const sorted = arr.slice();

  const n = sorted.length;
  let swapped;

  // Outer loop: each pass places the next-largest element at its final position.
  for (let i = 0; i < n - 1; i++) {
    swapped = false;

    // Inner loop: compare adjacent pairs up to the last unsorted index.
    for (let j = 0; j < n - 1 - i; j++) {
      if (sorted[j] > sorted[j + 1]) {
        // Swap adjacent elements if they are in the wrong order.
        [sorted[j], sorted[j + 1]] = [sorted[j + 1], sorted[j]];
        swapped = true;
      }
    }

    // Optimization: stop early if no swaps occurred in this pass.
    if (!swapped) break;
  }

  return sorted;
}

/* ---------- Example usage ---------- */
try {
  const data = [5, 1, 4, 2, 8, 0, 2];
  console.log('Original:', data);
  console.log('Sorted:  ', bubbleSort(data));
} catch (err) {
  console.error(err.message);
}
